export class CacheService{private entries=new Map<string,{value:unknown;expiresAt:number}>();set<T>(key:string,value:T,ttlMs=60_000){this.entries.set(key,{value:structuredClone(value),expiresAt:Date.now()+ttlMs})}get<T>(key:string):T|null{const entry=this.entries.get(key);if(!entry||entry.expiresAt<=Date.now()){this.entries.delete(key);return null}return structuredClone(entry.value as T)}invalidate(key?:string){if(key)this.entries.delete(key);else this.entries.clear()}}
